const people=[['101','Ayşe Yılmaz','Yönetim','Müsait'],['102','Mehmet Demir','Satış','Görüşmede'],['103','Elif Kaya','Satış','Çalıyor'],['104','Can Arslan','Destek','Müsait'],['105','Zeynep Aydın','Finans','Müsait'],['106','Emre Çelik','Destek','Görüşmede'],['107','Selin Aksoy','Operasyon','Müsait'],['108','Burak Şahin','Satış','Çevrimdışı'],['109','Deniz Yıldız','Yönetim','Müsait'],['110','Ece Koç','Finans','Çevrimdışı'],['111','Onur Güneş','Operasyon','Müsait'],['112','İrem Polat','Destek','Müsait']].map(([id,name,dept,status])=>({id,name,dept,status}));
let calls=[{ext:'102',from:'0212 555 01 24',seconds:148},{ext:'106',from:'0532 555 08 16',seconds:62}],filter='Tümü',pending=()=>{};const colors={'Müsait':'#229982','Görüşmede':'#4c80cf','Çalıyor':'#d59a29','Çevrimdışı':'#9aa6b6'},$=id=>document.getElementById(id),history=[];let toastTimer;
function log(text){history.unshift(text);$('activity').replaceChildren(...history.slice(0,4).map(t=>{const p=document.createElement('p');p.textContent=t;return p}));$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3200)}
function show(title,desc,body,fn){$('modalTitle').textContent=title;$('modalDesc').textContent=desc;$('modalBody').innerHTML=body;pending=fn;$('confirm').hidden=!fn;$('modal').showModal()}
$('cancel').onclick=()=>$('modal').close();$('confirm').onclick=()=>{if(pending&&pending()===false)return;$('modal').close()};
function render(){const available=people.filter(p=>p.status==='Müsait').length;$('stats').innerHTML=[['Toplam dahili',people.length],['Müsait',available],['Aktif görüşme',calls.length],['Bekleyen çağrı',3]].map(([label,n])=>`<div class="stat">${label}<strong>${n}<span style="font-size:12px;color:#95a5b5;font-weight:400"> ${label==='Bekleyen çağrı'?' / örnek':''}</span></strong></div>`).join('');$('filters').innerHTML=['Tümü','Müsait','Görüşmede','Çalıyor','Çevrimdışı'].map(s=>`<button class="${s===filter?'active':''}" data-filter="${s}">${s} · ${s==='Tümü'?people.length:people.filter(p=>p.status===s).length}</button>`).join('');const q=$('search').value.toLocaleLowerCase('tr');const list=people.filter(p=>(filter==='Tümü'||p.status===filter)&&($('department').value==='Tüm departmanlar'||p.dept===$('department').value)&&`${p.name} ${p.id}`.toLocaleLowerCase('tr').includes(q));$('empty').hidden=list.length>0;$('cards').innerHTML=list.map(p=>`<article class="card" data-status="${p.status}" style="--color:${colors[p.status]}"><div class="row"><span class="avatar">${p.name.split(' ').map(n=>n[0]).join('')}</span><span class="number">${p.id}</span></div><h3>${p.name}</h3><div class="dept">${p.dept}</div><div class="status">● &nbsp; ${p.status}</div><button class="action" data-person="${p.id}">${p.status==='Çalıyor'?'Çağrıyı yanıtla':p.status==='Görüşmede'?'Görüşmeyi görüntüle':p.status==='Çevrimdışı'?'Çevrimdışı':'↗ Dahiliyi ara'}</button></article>`).join('');renderCalls()}
const duration=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function renderCalls(){$('calls').innerHTML=calls.length?calls.map(c=>`<div class="call"><div class="row"><span class="small">Gelen çağrı → ${c.ext}</span><span class="small">${duration(c.seconds)}</span></div><strong>${c.from}</strong><span class="small">${people.find(p=>p.id===c.ext).name}</span><div><button data-transfer="${c.ext}">Aktar</button><button class="end" data-end="${c.ext}">Sonlandır</button></div></div>`).join(''):'<p class="small">Aktif çağrı yok.</p>'}
function startCall(id,from='Operatör · 100'){const p=people.find(p=>p.id===id);if(p.status!=='Müsait'){log('Bu dahili şu anda müsait değil.');return false}p.status='Görüşmede';calls.push({ext:id,from,seconds:0});log(`${id} ile demo görüşme başladı.`);render()}
$('cards').onclick=e=>{const id=e.target.dataset.person;if(!id)return;const p=people.find(x=>x.id===id);if(p.status==='Çalıyor'){p.status='Görüşmede';calls.push({ext:id,from:'0216 555 04 12',seconds:0});log('Demo çağrı yanıtlandı.');render()}else if(p.status==='Müsait')show('Dahiliyi ara',`${p.name} · ${id} için örnek çağrı başlatılacak. Gerçek arama yapılmaz.`,'',()=>startCall(id));else if(p.status==='Görüşmede'){document.querySelector('[data-transfer="'+id+'"]').focus()}else log('Dahili çevrimdışı.')};
$('calls').onclick=e=>{const end=e.target.dataset.end,id=e.target.dataset.transfer;if(end){calls=calls.filter(c=>c.ext!==end);people.find(p=>p.id===end).status='Müsait';log(`${end} demo görüşmesi sonlandırıldı.`);render()}if(id){const targets=people.filter(p=>p.status==='Müsait');show('Çağrıyı aktar','Aktarılacak müsait dahiliyi seçin. Bu işlem simülasyondur.',`<select id="target" aria-label="Aktarma hedefi">${targets.map(p=>`<option value="${p.id}">${p.id} · ${p.name}</option>`).join('')}</select>`,()=>{const t=$('target').value;if(!t)return false;calls.find(c=>c.ext===id).ext=t;people.find(p=>p.id===id).status='Müsait';people.find(p=>p.id===t).status='Görüşmede';log(`Demo çağrı ${id} → ${t} aktarıldı.`);render()})}};
$('newCall').onclick=()=>show('Yeni demo çağrı','Aramak için müsait bir dahili seçin.',`<select id="target" aria-label="Aranacak dahili">${people.filter(p=>p.status==='Müsait').map(p=>`<option value="${p.id}">${p.id} · ${p.name}</option>`).join('')}</select>`,()=>startCall($('target').value));
$('search').oninput=render;$('department').onchange=render;$('filters').onclick=e=>{if(e.target.dataset.filter){filter=e.target.dataset.filter;render()}};
$('queueContent').innerHTML=[['Satış',2,4,75],['Teknik destek',1,3,45],['Genel danışma',0,2,15]].map(([n,w,a,v])=>`<div class="queue"><div class="row"><b>${n}</b><span class="small">${w} bekleyen</span></div><div class="bar"><i style="width:${v}%"></i></div><span class="small">${a} temsilci · örnek durum</span></div>`).join('');
$('queueNav').onclick=()=>$('queues').scrollIntoView({behavior:'smooth',block:'center'});$('activityNav').onclick=()=>$('activity').scrollIntoView({behavior:'smooth',block:'center'});$('infoNav').onclick=()=>show('Bağlantı bilgisi','Demo modu — AMI bağlantısı yapılandırılmadı.','<p>Gerçek kullanım: Asterisk AMI → HOP sunucusu → WebSocket → tarayıcı.</p><p>AMI kullanıcı adı ve parolası sunucuda saklanır. Bu demoda kimlik bilgisi toplanmaz.</p>',null);render();setInterval(()=>{calls.forEach(c=>c.seconds++);renderCalls()},1000);

